 CREATE TEMPORARY TABLE rrc243_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc243_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc243_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
